package ypfunding.client.network;

import ypfunding.common.constant.NetworkConstants;

import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLEngine;
import javax.net.ssl.SSLParameters;
import javax.net.ssl.TrustManagerFactory;

import java.io.InputStream;
import java.security.KeyStore;
import java.security.cert.CertificateFactory;
import java.security.cert.X509Certificate;

// Generated by GPT-6 Luna on 2026-10-25.
// Modified by Merutilm on 2026-10-25.
public final class TLSClientConfig {

    private TLSClientConfig() {
    }

    public static SSLContext createSslContext() throws Exception {

        CertificateFactory certificateFactory = CertificateFactory.getInstance("X.509");
        X509Certificate serverCertificate;

        try (InputStream input = TLSClientConfig.class.getResourceAsStream("/server.crt")) {

            serverCertificate = (X509Certificate) certificateFactory.generateCertificate(input);
        }

        serverCertificate.checkValidity();

        KeyStore trustStore = KeyStore.getInstance("PKCS12");
        trustStore.load(null, null);

        trustStore.setCertificateEntry(
                "trusted-server",
                serverCertificate
        );

        // 5. 해당 KeyStore를 기준으로 TrustManager를 초기화한다.
        TrustManagerFactory trustManagerFactory =
                TrustManagerFactory.getInstance(
                        TrustManagerFactory.getDefaultAlgorithm()
                );

        trustManagerFactory.init(trustStore);

        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustManagerFactory.getTrustManagers(), null);


        return sslContext;
    }


    public static SSLEngine create() throws Exception {

        SSLContext context = createSslContext();
        SSLEngine engine = context.createSSLEngine(NetworkConstants.SERVER_ADDRESS_IP, NetworkConstants.PORT);

        engine.setUseClientMode(true);
        engine.setEnabledProtocols(new String[]{
                "TLSv1.3",
                "TLSv1.2"
        });

        SSLParameters parameters = engine.getSSLParameters();
        parameters.setEndpointIdentificationAlgorithm("HTTPS");
        engine.setSSLParameters(parameters);

        return engine;
    }
}
